/* 写真稼得は呼ばず、fieldの保存/読込だけを切り分ける。 */
static void pv_state(struct mCore*c,const char*stage){
 unsigned s=read32(c,QOL_SAVE_BLOCK1_SLOT);char hash[65];ct_screen(30,hash);char name[80];snprintf(name,sizeof(name),"visual-%s.ppm",stage);si_need(rename("catalog-page-30.ppm",name)==0,"visual screen");
 printf("{\"stage\":\"%s\",\"save_block\":%u,\"map\":[%u,%u],\"pos\":[%u,%u],\"saved_layout_id\":%u,\"counter\":%u,\"screen\":\"%s\",\"ram_headers\":[",stage,s,read8(c,s+4),read8(c,s+5),read16(c,s),read16(c,s+2),read16(c,s+0x32),read32(c,SI_COUNTER),hash);
 unsigned matches=0;for(unsigned a=0x02000000U;a<0x0203FFDCU;a+=4){if(read32(c,a+4)==0x09413750U&&read32(c,a+8)==0x09220D46U){unsigned l=read32(c,a);printf("%s{\"at\":%u,\"layout\":%u,\"layout_id\":%u,\"width\":%u,\"height\":%u,\"border\":%u,\"data\":%u,\"primary\":%u,\"secondary\":%u}",matches?",":"",a,l,read16(c,a+18),read32(c,l),read32(c,l+4),read32(c,l+8),read32(c,l+12),read32(c,l+16),read32(c,l+20));++matches;}}
 printf("]}\n");fflush(stdout);
}
int main(int argc,char**argv){
 si_need(argc==3,"visual args");char hash[65];sha256_file(argv[1],hash);si_need(!strcmp(hash,UC_ROM),"same candidate");sha256_file(argv[2],hash);si_need(!strcmp(hash,UC_FIXTURE),"same zero RP fixture");
 struct mLogger logger={.log=qol_log};mLogSetDefaultLogger(&logger);struct mCore*c=ph_setup(argv[1],argv[2]);
 uint8_t ledger[2048],party[600],flash[131072],check[131072];unsigned items[2048];lc_read(c,ledger);for(unsigned i=0;i<600;++i)party[i]=read8(c,QOL_PLAYER_PARTY+i);si_inventory(c,items);unsigned counter=read32(c,SI_COUNTER);
 pv_state(c,"warp");si_need(si_normal_save(c),"ordinary field-only Save");uc_same_ledger(c,ledger);uc_same_inventory(c,items,party);si_need(read32(c,SI_COUNTER)==counter+1,"single normal Save");pv_state(c,"saved");uc_copy_flash(c,flash);qol_close(c);
 c=ct_open(argv[1],argv[2]);si_guard(c);ph_stance(c);pv_state(c,"cold");uc_same_ledger(c,ledger);uc_same_inventory(c,items,party);uc_copy_flash(c,check);si_need(!memcmp(flash,check,131072),"readonly Continue");si_need(read32(c,SI_COUNTER)==counter+1,"no extra save");qol_close(c);si_need(!log_problem_count,"clean emulator");
 printf("{\"status\":\"PASS_DIAGNOSTIC_ONLY\",\"native_processes\":1,\"fresh_cores\":%u,\"rp_earning_runs\":0,\"rom_changes\":0,\"guarded_host_writes\":0,\"manual_saves\":1}\n",si_cores);return 0;
}

static struct mCore*pv_save_setup(const char*rom,const char*save){
 struct mCore*c=ct_open(rom,save);unsigned events=read32(c,0x092C0B20U),bgs=read32(c,events+16),script=read32(c,bgs+8);
 si_need(events==0x09413750U&&bgs==0x09413708U&&script==0x093C05E4U&&read16(c,bgs)==48&&read16(c,bgs+2)==4,"actual photo background root");
 printf("{\"binding\":\"map96/37-background0\",\"events\":%u,\"backgrounds\":%u,\"script\":%u,\"x\":48,\"y\":4,\"activity\":5,\"points\":6,\"cap\":6}\n",events,bgs,script);fflush(stdout);
 run_key_frames(c,0,2);
 (void)qol_call5_preserving(c,QOL_SET_WARP_DESTINATION,96,37,255,48,5);
 (void)call_preserving(c,QOL_RESET_INITIAL_AVATAR,0,0,0,0);
 (void)call_preserving(c,QOL_WARP_INTO_MAP,0,0,0,0);
 qol_write32(c,QOL_FIELD_CALLBACK_SLOT,QOL_DEFAULT_WARP_EXIT);
 (void)call_preserving(c,QOL_SET_MAIN_CALLBACK2,QOL_CB2_LOAD_MAP,0,0,0); /* scheduler引数準備までfixture区間 */
 for(unsigned i=0;i<900;++i)uc_frame(c,0);ph_stance(c);
 si_need(read8(c,SI_VOL+28)==0&&read8(c,SI_VOL+34)==0&&si_read16(c,SI_VOL+20)==65535,"real services only");
 return c;
}
/* 写真稼得は呼ばず、fieldの保存/読込だけを切り分ける。 */
static void pv_state(struct mCore*c,const char*stage){
 unsigned s=read32(c,QOL_SAVE_BLOCK1_SLOT);char hash[65];ct_screen(30,hash);char name[80];snprintf(name,sizeof(name),"visual-%s.ppm",stage);si_need(rename("catalog-page-30.ppm",name)==0,"visual screen");
 printf("{\"stage\":\"%s\",\"save_block\":%u,\"map\":[%u,%u],\"pos\":[%u,%u],\"saved_layout_id\":%u,\"counter\":%u,\"screen\":\"%s\",\"ram_headers\":[",stage,s,read8(c,s+4),read8(c,s+5),read16(c,s),read16(c,s+2),read16(c,s+0x32),read32(c,SI_COUNTER),hash);
 unsigned matches=0;for(unsigned a=0x02000000U;a<0x0203FFDCU;a+=4){if(read32(c,a+4)==0x09413750U&&read32(c,a+8)==0x09220D46U){unsigned l=read32(c,a);printf("%s{\"at\":%u,\"layout\":%u,\"layout_id\":%u,\"width\":%u,\"height\":%u,\"border\":%u,\"data\":%u,\"primary\":%u,\"secondary\":%u}",matches?",":"",a,l,read16(c,a+18),read32(c,l),read32(c,l+4),read32(c,l+8),read32(c,l+12),read32(c,l+16),read32(c,l+20));++matches;}}
 printf("]}\n");fflush(stdout);
}

int main(int argc,char**argv){
 si_need(argc==3,"diagnostic args");char hash[65];sha256_file(argv[1],hash);si_need(!strcmp(hash,UC_ROM),"candidate");sha256_file(argv[2],hash);si_need(!strcmp(hash,UC_FIXTURE),"zero RP fixture");
 struct mLogger logger={.log=qol_log};mLogSetDefaultLogger(&logger);struct mCore*c=pv_save_setup(argv[1],argv[2]);
 uint8_t ledger[2048],party[600],flash[131072],check[131072];unsigned items[2048];lc_read(c,ledger);for(unsigned i=0;i<600;++i)party[i]=read8(c,QOL_PLAYER_PARTY+i);si_inventory(c,items);unsigned counter=read32(c,SI_COUNTER);
 pv_state(c,"direct-before");unsigned result=si_transaction(c,0x09377661U,0,0,0,false);si_guard(c);si_need(result==1&&si_saves==1&&read32(c,SI_COUNTER)==counter+1,"single real QOL save on scheduler fixture");
 uc_same_ledger(c,ledger);uc_same_inventory(c,items,party);uc_copy_flash(c,flash);qol_close(c);
 c=ct_open(argv[1],argv[2]);si_guard(c);ph_stance(c);pv_state(c,"direct-cold");uc_same_ledger(c,ledger);uc_same_inventory(c,items,party);uc_copy_flash(c,check);si_need(!memcmp(flash,check,131072),"readonly Continue");si_need(read32(c,SI_COUNTER)==counter+1,"no extra save");qol_close(c);si_need(!log_problem_count,"clean emulator");
 printf("{\"status\":\"PASS_DIAGNOSTIC_ONLY\",\"native_processes\":1,\"fresh_cores\":%u,\"rp_earning_runs\":0,\"rom_changes\":0,\"scheduler_fixture_calls\":1,\"guarded_host_writes\":0,\"manual_saves\":0}\n",si_cores);return 0;
}
